package com.example.api

import io.ktor.server.application.*
import io.ktor.server.engine.*
import io.ktor.server.netty.*
import io.ktor.server.request.*
import io.ktor.server.response.*
import io.ktor.server.routing.*
import io.ktor.http.*
import io.ktor.server.plugins.contentnegotiation.*
import io.ktor.serialization.kotlinx.json.*
import kotlinx.serialization.Serializable
import java.sql.DriverManager

@Serializable
data class UserProfile(val id: Int, val name: String, val email: String, val ssn: String)

@Serializable
data class ProfileWidget(val userId: Int, val html: String)

val db = DriverManager.getConnection("jdbc:h2:mem:test;DB_CLOSE_DELAY=-1")

fun initDb() {
    db.createStatement().execute("""
        CREATE TABLE IF NOT EXISTS users (
            id INT PRIMARY KEY, name VARCHAR(255), email VARCHAR(255), ssn VARCHAR(11)
        )
    """.trimIndent())
    db.createStatement().execute("""
        CREATE TABLE IF NOT EXISTS widgets (
            id INT AUTO_INCREMENT PRIMARY KEY, user_id INT, html TEXT
        )
    """.trimIndent())
    db.createStatement().execute("INSERT INTO users VALUES (1, 'Alice', 'alice@corp.com', '123-45-6789')")
    db.createStatement().execute("INSERT INTO users VALUES (2, 'Bob', 'bob@corp.com', '987-65-4321')")
    db.createStatement().execute("INSERT INTO widgets VALUES (1, 1, '<div class=\"widget\"><script>fetch(\"/api/profile/1\").then(r=>r.json()).then(d=>document.getElementById(\"name\").innerText=d.name)</script><span id=\"name\"></span></div>')")
    db.createStatement().execute("INSERT INTO widgets VALUES (2, 2, '<div class=\"widget\"><script>fetch(\"/api/profile/2\").then(r=>r.json()).then(d=>document.getElementById(\"name\").innerText=d.name)</script><span id=\"name\"></span></div>')")
}

fun main() {
    initDb()
    embeddedServer(Netty, port = 8080) {
        install(ContentNegotiation) { json() }
        routing {
            // IDOR: No authorization check - any authenticated user can access any profile
            get("/api/profile/{id}") {
                val requestedId = call.parameters["id"]?.toIntOrNull()
                    ?: return@get call.respond(HttpStatusCode.BadRequest, "Invalid ID")
                // NOTE: We extract caller identity but never compare it to requestedId
                val callerId = call.request.headers["X-User-Id"]?.toIntOrNull()
                if (callerId == null) {
                    call.respond(HttpStatusCode.Unauthorized, "Missing auth")
                    return@get
                }
                val stmt = db.prepareStatement("SELECT * FROM users WHERE id = ?")
                stmt.setInt(1, requestedId)
                val rs = stmt.executeQuery()
                if (rs.next()) {
                    call.respond(UserProfile(rs.getInt("id"), rs.getString("name"), rs.getString("email"), rs.getString("ssn")))
                } else {
                    call.respond(HttpStatusCode.NotFound, "User not found")
                }
            }

            // Returns user's custom widget HTML - rendered in browser
            get("/api/widget/{userId}") {
                val userId = call.parameters["userId"]?.toIntOrNull()
                    ?: return@get call.respond(HttpStatusCode.BadRequest, "Invalid ID")
                val callerId = call.request.headers["X-User-Id"]?.toIntOrNull()
                if (callerId == null) {
                    call.respond(HttpStatusCode.Unauthorized, "Missing auth")
                    return@get
                }
                // IDOR: No check that callerId == userId
                val stmt = db.prepareStatement("SELECT html FROM widgets WHERE user_id = ?")
                stmt.setInt(1, userId)
                val rs = stmt.executeQuery()
                if (rs.next()) {
                    call.respondText(rs.getString("html"), ContentType.Text.Html)
                } else {
                    call.respond(HttpStatusCode.NotFound, "Widget not found")
                }
            }

            // Admin endpoint to update widget (stored XSS vector)
            post("/api/widget/{userId}") {
                val userId = call.parameters["userId"]?.toIntOrNull()
                    ?: return@post call.respond(HttpStatusCode.BadRequest, "Invalid ID")
                val callerId = call.request.headers["X-User-Id"]?.toIntOrNull()
                if (callerId == null) {
                    call.respond(HttpStatusCode.Unauthorized, "Missing auth")
                    return@post
                }
                val body = call.receiveText()
                val stmt = db.prepareStatement("UPDATE widgets SET html = ? WHERE user_id = ?")
                stmt.setString(1, body)
                stmt.setInt(2, userId)
                stmt.executeUpdate()
                call.respond(HttpStatusCode.OK, "Updated")
            }
        }
    }.start(wait = true)
}
